"""
NutriCheck - Person 2
Dataset Statistics

Generates statistics for the already-preprocessed
medical transcription dataset.

This module does NOT modify the dataset.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

import pandas as pd


class MedicalDatasetStatistics:
    """Generate statistics for the NutriCheck dataset."""

    def __init__(self, dataset_path: str | Path) -> None:
        self.dataset_path = Path(dataset_path)

    # =========================================================
    # Load Dataset
    # =========================================================

    def load(self) -> pd.DataFrame:
        """Load the CSV dataset."""

        if not self.dataset_path.exists():
            raise FileNotFoundError(
                f"Dataset not found: {self.dataset_path}"
            )

        if not self.dataset_path.is_file():
            raise ValueError(
                f"Dataset path is not a file: {self.dataset_path}"
            )

        if self.dataset_path.suffix.lower() != ".csv":
            raise ValueError(
                "Expected a CSV dataset."
            )

        dataframe = pd.read_csv(self.dataset_path)

        return dataframe

    # =========================================================
    # Basic Statistics
    # =========================================================

    def basic_statistics(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, Any]:
        """Generate basic dataset statistics."""

        return {
            "rows": int(dataframe.shape[0]),
            "columns": int(dataframe.shape[1]),
            "column_names": list(dataframe.columns),
            "missing_values": {
                column: int(
                    dataframe[column].isna().sum()
                )
                for column in dataframe.columns
            },
            "duplicate_rows": int(
                dataframe.duplicated().sum()
            ),
        }

    # =========================================================
    # Medical Specialty Distribution
    # =========================================================

    def specialty_distribution(
        self,
        dataframe: pd.DataFrame,
    ) -> pd.Series:
        """Count records for each medical specialty."""

        if "medical_specialty" not in dataframe.columns:
            raise ValueError(
                "Column 'medical_specialty' not found."
            )

        return (
            dataframe["medical_specialty"]
            .fillna("Unknown")
            .value_counts()
        )

    # =========================================================
    # Transcription Statistics
    # =========================================================

    def transcription_statistics(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, float]:
        """Generate statistics about transcriptions."""

        if "transcription" not in dataframe.columns:
            raise ValueError(
                "Column 'transcription' not found."
            )

        transcription = (
            dataframe["transcription"]
            .fillna("")
            .astype(str)
        )

        character_lengths = (
            transcription.str.len()
        )

        word_lengths = (
            transcription
            .str.split()
            .str.len()
        )

        return {
            "average_characters": float(
                character_lengths.mean()
            ),
            "average_words": float(
                word_lengths.mean()
            ),
            "minimum_words": float(
                word_lengths.min()
            ),
            "maximum_words": float(
                word_lengths.max()
            ),
        }

    # =========================================================
    # Generate Complete Report
    # =========================================================

    def generate_report(self) -> dict[str, Any]:
        """Generate complete statistics report."""

        dataframe = self.load()

        basic = self.basic_statistics(
            dataframe
        )

        specialties = self.specialty_distribution(
            dataframe
        )

        transcription = self.transcription_statistics(
            dataframe
        )

        return {
            "dataset": str(self.dataset_path),
            "basic_statistics": basic,
            "specialty_distribution": {
                str(index): int(value)
                for index, value in specialties.items()
            },
            "transcription_statistics": transcription,
        }


# =============================================================
# Find Dataset
# =============================================================

def find_dataset() -> Path:
    """
    Find the medical_transcriptions CSV.

    FIX (NLP integration): the original version only looked in Google Colab's /content
    folder, so it failed on every normal computer even though the README says the data
    lives in data/raw/. The search order is now:

        1. environment variable NUTRICHECK_DATASET (a path to the CSV)
        2. <project root>/data/raw/            (the location documented in the README)
        3. the current working directory
        4. /content                            (Google Colab, the original behaviour)

    in each folder it accepts  medical_transcriptions.csv,
    medical_transcriptions.csv.csv (accidental double extension) and
    medical_transcriptions*.csv.
    """
    import os

    names = ["medical_transcriptions.csv", "medical_transcriptions.csv.csv"]

    env = os.getenv("NUTRICHECK_DATASET")
    if env:
        env_path = Path(env)
        if env_path.is_file():
            return env_path

    project_root = Path(__file__).resolve().parents[2]
    folders = [
        project_root / "data" / "raw",
        Path.cwd(),
        Path("/content"),
    ]

    for folder in folders:
        for filename in names:
            candidate = folder / filename
            if candidate.is_file():
                return candidate
        if folder.is_dir():
            matches = sorted(folder.glob("medical_transcriptions*.csv"))
            if matches:
                return matches[0]

    searched = "\n".join(f"  {f}" for f in folders)
    raise FileNotFoundError(
        "Could not find the medical transcription dataset.\n"
        "Put medical_transcriptions.csv in data/raw/ or set NUTRICHECK_DATASET.\n"
        f"Searched:\n{searched}"
    )


# =============================================================
# Print Report
# =============================================================

def print_report(
    report: dict[str, Any],
) -> None:
    """Print the statistics report."""

    print()
    print("=" * 70)
    print("NutriCheck - Person 2 Dataset Statistics")
    print("=" * 70)

    print()
    print(f"Dataset: {report['dataset']}")

    # ---------------------------------------------------------
    # Basic statistics
    # ---------------------------------------------------------

    basic = report["basic_statistics"]

    print()
    print("-" * 70)
    print("BASIC STATISTICS")
    print("-" * 70)

    print(f"Rows: {basic['rows']}")
    print(f"Columns: {basic['columns']}")

    print()
    print("Columns:")

    for column in basic["column_names"]:
        print(f"  • {column}")

    # ---------------------------------------------------------
    # Missing values
    # ---------------------------------------------------------

    print()
    print("-" * 70)
    print("MISSING VALUES")
    print("-" * 70)

    for column, count in basic["missing_values"].items():
        print(f"  {column}: {count}")

    # ---------------------------------------------------------
    # Duplicates
    # ---------------------------------------------------------

    print()
    print("-" * 70)
    print("DUPLICATE ROWS")
    print("-" * 70)

    print(
        f"Duplicate rows: "
        f"{basic['duplicate_rows']}"
    )

    # ---------------------------------------------------------
    # Medical specialties
    # ---------------------------------------------------------

    print()
    print("-" * 70)
    print("MEDICAL SPECIALTY DISTRIBUTION")
    print("-" * 70)

    for specialty, count in (
        report["specialty_distribution"].items()
    ):
        print(f"  {specialty}: {count}")

    # ---------------------------------------------------------
    # Transcription statistics
    # ---------------------------------------------------------

    print()
    print("-" * 70)
    print("TRANSCRIPTION STATISTICS")
    print("-" * 70)

    transcription = report[
        "transcription_statistics"
    ]

    print(
        f"Average characters: "
        f"{transcription['average_characters']:.2f}"
    )

    print(
        f"Average words: "
        f"{transcription['average_words']:.2f}"
    )

    print(
        f"Minimum words: "
        f"{transcription['minimum_words']:.0f}"
    )

    print(
        f"Maximum words: "
        f"{transcription['maximum_words']:.0f}"
    )

    print()
    print("=" * 70)


# =============================================================
# Main
# =============================================================

if __name__ == "__main__":

    try:

        dataset_path = find_dataset()

        print(
            f"\nUsing dataset:\n"
            f"{dataset_path}\n"
        )

        statistics = MedicalDatasetStatistics(
            dataset_path
        )

        report = statistics.generate_report()

        print_report(report)

    except Exception as error:

        print()
        print("ERROR:")
        print(error)



